cat > probes/convolution-reference.mlpl <<'EOF'
# Reference construction for the convolution blocker record. Every gap in
# docs/sw-mlpl-blocker.md is a place where this file is harder to read than the
# equation it implements; this probe exists so the "expected once shipped"
# column of that record is checkable against a known-good result.
#
# Zhao, Wang, Wang & Liu (2018) §2.1:
#   y[r,x,y] = SUM_q SUM_u SUM_v W[r,q,u,v] * X[q,x+u,y+v]
#
# Exits zero on the current binary. The native conv2d builtin is an independent
# oracle here, not an implementation.

def u:conv_windows(x, kh, kw) {
  "Build a [out_y, out_x, channel, kernel_y, kernel_x] sliding-window tensor from a [channel, image_y, image_x] input, standing in for the missing general windows primitive (C1).";
  channels = take(shape(x), 0, 0);
  height = take(shape(x), 0, 1);
  width = take(shape(x), 0, 2);
  out_h = height - kh + 1;
  out_w = width - kw + 1;
  row_mask = lt(range(height), out_h);
  col_mask = lt(range(width), out_w);
  stacked = fill([0, channels, out_h, out_w], 0);
  u = 0;
  while lt(u, kh) {
    v = 0;
    while lt(v, kw) {
      shifted = rotate(rotate(x, u, 1), v, 2);
      trimmed = compress(col_mask, compress(row_mask, shifted, 1), 2);
      stacked = concat(stacked, reshape(trimmed, [1, channels, out_h, out_w]), 0);
      v = v + 1
    };
    u = u + 1
  };
  transpose_axes(reshape(stacked, [kh, kw, channels, out_h, out_w]), [3, 4, 2, 0, 1])
